<script setup>
import { router, useForm } from '@inertiajs/vue3'
import PortalLayout from '@/Layouts/PortalLayout.vue'
const props=defineProps({doctor:Object,organizations:Array,clinics:Array,members:Array,contracts:Array,payrolls:Array,leaveBalances:Array,performance:Array,coverageSuggestions:Array,month:String,currentYear:Number})
const contractForm=useForm({organization_id:props.organizations?.[0]?.id??'',clinic_id:'',staff_user_id:'',compensation_type:'monthly',base_monthly_salary:0,hourly_rate:0,standard_monthly_minutes:9600,overtime_multiplier_basis_points:15000,annual_leave_days:26,paid_leave_types:['annual','sick','mission'],effective_from:new Date().toISOString().slice(0,10),effective_until:'',notes:''})
const balanceForm=useForm({organization_id:props.organizations?.[0]?.id??'',staff_user_id:'',year:props.currentYear,entitled_days:26,carry_over_days:0,adjustment_days:0,notes:''})
const payrollForm=useForm({organization_id:props.organizations?.[0]?.id??'',clinic_id:'',staff_user_id:'',period_start:new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10),period_end:new Date().toISOString().slice(0,10),allowance_amount:0,deduction_amount:0,notes:''})
const clinicsFor=form=>props.clinics.filter(c=>String(c.organization_id)===String(form.organization_id))
const membersFor=form=>props.members.filter(m=>String(m.organization_id)===String(form.organization_id))
const money=v=>new Intl.NumberFormat('fa-IR').format(Number(v||0))+' ریال'
const hours=v=>Math.floor(Number(v||0)/60)+' ساعت و '+(Number(v||0)%60)+' دقیقه'
const names=m=>(m.name||'')+' '+(m.family||'')
const createContract=()=>contractForm.post(route('portal.staff-management.contracts.store'),{onSuccess:()=>contractForm.reset('staff_user_id','base_monthly_salary','hourly_rate','notes')})
const saveBalance=()=>balanceForm.post(route('portal.staff-management.leave-balances.store'))
const createPayroll=()=>payrollForm.post(route('portal.staff-management.payrolls.store'),{onSuccess:()=>payrollForm.reset('allowance_amount','deduction_amount','notes')})
const approvePayroll=id=>{if(window.confirm('فیش حقوقی تأیید شود؟'))router.patch(route('portal.staff-management.payrolls.approve',id))}
const payPayroll=id=>{const method=window.prompt('روش پرداخت: cash / card / transfer / online / cheque','transfer');if(!method)return;const reference=window.prompt('شماره پیگیری یا مرجع (اختیاری)','');router.post(route('portal.staff-management.payrolls.pay',id),{payment_method:method,payment_reference:reference||null})}
const assign=(shift,candidate)=>{if(!window.confirm('ثبت '+names(candidate)+' به‌عنوان جانشین '+shift.staff_name+'؟'))return;router.post(route('portal.staff-management.replacements.store'),{organization_id:shift.organization_id,clinic_id:shift.clinic_id,absent_staff_user_id:shift.absent_staff_user_id,replacement_staff_user_id:candidate.user_id,work_date:shift.work_date,start_time:String(shift.start_time).slice(0,5),end_time:String(shift.end_time).slice(0,5)})}
const status=s=>({draft:'پیش‌نویس',approved:'تأییدشده',paid:'پرداخت‌شده'})[s]||s
</script>
<template>
<PortalLayout :doctor="doctor"><main dir="rtl" class="mx-auto max-w-7xl space-y-5 p-3 sm:p-5">
<header class="rounded-3xl bg-gradient-to-l from-slate-950 to-teal-800 p-6 text-white"><p class="text-xs font-bold text-teal-200">PRONEEX · HUMAN CAPITAL</p><h1 class="mt-2 text-2xl font-black">موتور هوشمند منابع انسانی</h1><p class="mt-2 text-sm text-white/80">قرارداد، سهمیه مرخصی، محاسبه حقوق، اضافه‌کاری، پوشش شیفت و شاخص‌های عملیاتی کارکنان</p></header>
<section class="grid grid-cols-2 gap-3 lg:grid-cols-4"><article class="rounded-2xl border bg-white p-4"><p class="text-xs text-slate-500">قراردادهای فعال در بازه</p><b class="mt-2 block text-2xl">{{contracts.length}}</b></article><article class="rounded-2xl border bg-white p-4"><p class="text-xs text-slate-500">فیش‌های حقوقی</p><b class="mt-2 block text-2xl">{{payrolls.length}}</b></article><article class="rounded-2xl border bg-white p-4"><p class="text-xs text-slate-500">فیش‌های در انتظار تأیید</p><b class="mt-2 block text-2xl text-amber-600">{{payrolls.filter(p=>p.status==='draft').length}}</b></article><article class="rounded-2xl border bg-white p-4"><p class="text-xs text-slate-500">شیفت‌های نیازمند جانشین امروز</p><b class="mt-2 block text-2xl text-rose-600">{{coverageSuggestions.length}}</b></article></section>
<section class="rounded-2xl border bg-white p-4"><h2 class="font-black">تعریف قرارداد جبران خدمات</h2><p class="mt-1 text-xs leading-6 text-slate-500">تمام مبالغ به ریال هستند. قرارداد جدید، قرارداد باز قبلی همان کارمند/شعبه را از روز قبل می‌بندد.</p><form @submit.prevent="createContract" class="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
<select v-model="contractForm.organization_id" required class="rounded-xl border-slate-300 text-sm"><option value="">مجموعه</option><option v-for="o in organizations" :key="o.id" :value="o.id">{{o.name}}</option></select>
<select v-model="contractForm.clinic_id" required class="rounded-xl border-slate-300 text-sm"><option value="">شعبه</option><option v-for="c in clinicsFor(contractForm)" :key="c.id" :value="c.id">{{c.name}}</option></select>
<select v-model="contractForm.staff_user_id" required class="rounded-xl border-slate-300 text-sm"><option value="">کارمند</option><option v-for="m in membersFor(contractForm)" :key="m.user_id" :value="m.user_id">{{names(m)}}</option></select>
<select v-model="contractForm.compensation_type" class="rounded-xl border-slate-300 text-sm"><option value="monthly">حقوق ماهانه</option><option value="hourly">دستمزد ساعتی</option></select>
<label v-if="contractForm.compensation_type==='monthly'" class="text-xs text-slate-500">حقوق پایه ماهانه (ریال)<input v-model.number="contractForm.base_monthly_salary" type="number" min="1" required class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<label v-else class="text-xs text-slate-500">نرخ هر ساعت (ریال)<input v-model.number="contractForm.hourly_rate" type="number" min="1" required class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<label class="text-xs text-slate-500">دقایق استاندارد ماهانه<input v-model.number="contractForm.standard_monthly_minutes" type="number" min="60" max="30000" required class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<label class="text-xs text-slate-500">ضریب اضافه‌کاری (درصد)<input :value="contractForm.overtime_multiplier_basis_points/100" @input="contractForm.overtime_multiplier_basis_points=Math.round(Number($event.target.value)*100)" type="number" min="100" max="300" class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<label class="text-xs text-slate-500">مرخصی سالانه (روز)<input v-model.number="contractForm.annual_leave_days" type="number" min="0" max="60" step=".5" class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<label class="text-xs text-slate-500">شروع قرارداد<input v-model="contractForm.effective_from" type="date" required class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<label class="text-xs text-slate-500">پایان قرارداد<input v-model="contractForm.effective_until" type="date" class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<div class="rounded-xl bg-slate-50 p-3 text-xs sm:col-span-2"><p class="mb-2 font-bold">مرخصی با حقوق</p><div class="flex flex-wrap gap-4"><label v-for="t in [{v:'annual',t:'استحقاقی'},{v:'sick',t:'استعلاجی'},{v:'mission',t:'مأموریت'}]" :key="t.v" class="flex items-center gap-2"><input v-model="contractForm.paid_leave_types" type="checkbox" :value="t.v">{{t.t}}</label></div></div>
<input v-model="contractForm.notes" placeholder="یادداشت قرارداد" class="rounded-xl border-slate-300 text-sm"><button :disabled="contractForm.processing" class="rounded-xl bg-teal-700 p-3 text-sm font-bold text-white sm:col-span-4">ثبت قرارداد</button></form>
<div class="mt-4 overflow-x-auto"><table class="w-full min-w-[700px] text-right text-xs"><thead class="bg-slate-50"><tr><th class="p-3">کارمند</th><th class="p-3">شعبه</th><th class="p-3">نوع</th><th class="p-3">حقوق پایه / نرخ ساعت</th><th class="p-3">ضریب اضافه‌کاری</th><th class="p-3">اعتبار</th></tr></thead><tbody><tr v-for="c in contracts" :key="c.id" class="border-t"><td class="p-3">{{c.staff_name}} {{c.staff_family||''}}</td><td class="p-3">{{c.clinic_name}}</td><td class="p-3">{{c.compensation_type==='monthly'?'ماهانه':'ساعتی'}}</td><td class="p-3">{{money(c.compensation_type==='monthly'?c.base_monthly_salary:c.hourly_rate)}}</td><td class="p-3">{{c.overtime_multiplier_basis_points/100}}٪</td><td class="p-3">{{c.effective_from}} تا {{c.effective_until||'نامحدود'}}</td></tr></tbody></table></div></section>
<section class="rounded-2xl border bg-white p-4"><h2 class="font-black">مانده مرخصی سالانه</h2><p class="mt-1 text-xs text-slate-500">سهمیه، انتقال از سال قبل و تعدیل را ثبت کنید؛ مصرف از درخواست‌های استحقاقی تأییدشده محاسبه می‌شود.</p><form @submit.prevent="saveBalance" class="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
<select v-model="balanceForm.organization_id" required class="rounded-xl border-slate-300 text-sm"><option v-for="o in organizations" :key="o.id" :value="o.id">{{o.name}}</option></select>
<select v-model="balanceForm.staff_user_id" required class="rounded-xl border-slate-300 text-sm"><option value="">کارمند</option><option v-for="m in membersFor(balanceForm)" :key="m.user_id" :value="m.user_id">{{names(m)}}</option></select>
<input v-model.number="balanceForm.year" type="number" min="2020" max="2100" class="rounded-xl border-slate-300 text-sm"><input v-model.number="balanceForm.entitled_days" type="number" min="0" max="60" step=".5" placeholder="سهمیه روز" class="rounded-xl border-slate-300 text-sm">
<input v-model.number="balanceForm.carry_over_days" type="number" min="0" max="60" step=".5" placeholder="انتقال از سال قبل" class="rounded-xl border-slate-300 text-sm"><input v-model.number="balanceForm.adjustment_days" type="number" min="-60" max="60" step=".5" placeholder="تعدیل مثبت/منفی" class="rounded-xl border-slate-300 text-sm">
<input v-model="balanceForm.notes" placeholder="توضیحات" class="rounded-xl border-slate-300 text-sm"><button :disabled="balanceForm.processing" class="rounded-xl bg-slate-900 p-3 text-sm font-bold text-white">ذخیره سهمیه</button></form>
<div class="mt-4 overflow-x-auto"><table class="w-full min-w-[600px] text-right text-xs"><thead class="bg-slate-50"><tr><th class="p-3">کارمند</th><th class="p-3">سال</th><th class="p-3">سهمیه</th><th class="p-3">انتقال</th><th class="p-3">مصرف</th><th class="p-3">مانده</th></tr></thead><tbody><tr v-for="b in leaveBalances" :key="b.id" class="border-t"><td class="p-3">{{b.staff_name}} {{b.staff_family||''}}</td><td class="p-3">{{b.year}}</td><td class="p-3">{{b.entitled_days}}</td><td class="p-3">{{b.carry_over_days}}</td><td class="p-3">{{b.used_days}}</td><td class="p-3 font-bold text-teal-700">{{b.remaining_days}}</td></tr><tr v-if="!leaveBalances.length"><td colspan="6" class="p-4 text-center text-slate-400">برای این سال سهمیه‌ای ثبت نشده است.</td></tr></tbody></table></div></section>
<section class="rounded-2xl border bg-white p-4"><h2 class="font-black">محاسبه و ایجاد فیش حقوقی</h2><p class="mt-1 text-xs leading-6 text-slate-500">محاسبه بر اساس حضور ثبت‌شده، برنامه کاری، مرخصی تأییدشده با حقوق و قرارداد فعال انجام می‌شود. فیش ابتدا پیش‌نویس است.</p>
<form @submit.prevent="createPayroll" class="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
<select v-model="payrollForm.organization_id" required class="rounded-xl border-slate-300 text-sm"><option v-for="o in organizations" :key="o.id" :value="o.id">{{o.name}}</option></select>
<select v-model="payrollForm.clinic_id" required class="rounded-xl border-slate-300 text-sm"><option value="">شعبه</option><option v-for="c in clinicsFor(payrollForm)" :key="c.id" :value="c.id">{{c.name}}</option></select>
<select v-model="payrollForm.staff_user_id" required class="rounded-xl border-slate-300 text-sm"><option value="">کارمند</option><option v-for="m in membersFor(payrollForm)" :key="m.user_id" :value="m.user_id">{{names(m)}}</option></select>
<label class="text-xs text-slate-500">شروع دوره<input v-model="payrollForm.period_start" type="date" required class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<label class="text-xs text-slate-500">پایان دوره<input v-model="payrollForm.period_end" type="date" required class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<label class="text-xs text-slate-500">مزایا (ریال)<input v-model.number="payrollForm.allowance_amount" type="number" min="0" class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<label class="text-xs text-slate-500">کسورات (ریال)<input v-model.number="payrollForm.deduction_amount" type="number" min="0" class="mt-1 w-full rounded-xl border-slate-300 text-sm"></label>
<input v-model="payrollForm.notes" placeholder="یادداشت فیش" class="rounded-xl border-slate-300 text-sm"><button :disabled="payrollForm.processing" class="rounded-xl bg-indigo-700 p-3 text-sm font-bold text-white sm:col-span-2 lg:col-span-4">محاسبه و ایجاد پیش‌نویس فیش</button></form>
<div class="mt-4 overflow-x-auto"><table class="w-full min-w-[1000px] text-right text-xs"><thead class="bg-slate-50"><tr><th class="p-3">کارمند</th><th class="p-3">دوره</th><th class="p-3">کارکرد</th><th class="p-3">اضافه‌کاری</th><th class="p-3">حقوق پایه</th><th class="p-3">مبلغ اضافه‌کاری</th><th class="p-3">ناخالص</th><th class="p-3">کسورات</th><th class="p-3">خالص</th><th class="p-3">وضعیت</th><th class="p-3">عملیات</th></tr></thead><tbody><tr v-for="p in payrolls" :key="p.id" class="border-t"><td class="p-3">{{p.staff?.name}} {{p.staff?.family||''}}</td><td class="p-3">{{p.period_start}} تا {{p.period_end}}</td><td class="p-3">{{hours(p.worked_minutes)}}</td><td class="p-3">{{hours(p.overtime_minutes)}}</td><td class="p-3">{{money(p.base_pay)}}</td><td class="p-3">{{money(p.overtime_pay)}}</td><td class="p-3">{{money(p.gross_amount)}}</td><td class="p-3">{{money(p.deduction_amount)}}</td><td class="p-3 font-black">{{money(p.net_amount)}}</td><td class="p-3">{{status(p.status)}}</td><td class="p-3"><div class="flex gap-1"><button v-if="p.status==='draft'" @click="approvePayroll(p.id)" class="rounded-lg bg-emerald-100 px-2 py-2 text-emerald-800">تأیید</button><button v-if="p.status==='approved'" @click="payPayroll(p.id)" class="rounded-lg bg-indigo-100 px-2 py-2 text-indigo-800">پرداخت</button></div></td></tr><tr v-if="!payrolls.length"><td colspan="11" class="p-5 text-center text-slate-400">برای این بازه فیش حقوقی ثبت نشده است.</td></tr></tbody></table></div></section>
<section class="rounded-2xl border border-amber-200 bg-amber-50 p-4"><h2 class="font-black text-amber-950">پیشنهاد پوشش شیفت امروز</h2><p class="mt-1 text-xs leading-6 text-amber-900">بر اساس شیفت شروع‌شده بدون ورود، عضویت در شعبه و نبود هم‌پوشانی برنامه/مرخصی. ثبت جانشین، ثبت ورود و خروج واقعی را جایگزین نمی‌کند.</p>
<div v-for="s in coverageSuggestions" :key="s.organization_id+'-'+s.clinic_id+'-'+s.absent_staff_user_id" class="mt-3 rounded-xl border border-amber-200 bg-white p-3"><div class="flex flex-wrap justify-between gap-2 text-sm"><b>{{s.staff_name}} {{s.staff_family||''}}</b><span>{{String(s.start_time).slice(0,5)}} تا {{String(s.end_time).slice(0,5)}}</span></div><p class="mt-2 text-xs text-slate-500">جانشین پیشنهادی:</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="candidate in s.candidates" :key="candidate.user_id" @click="assign(s,candidate)" class="rounded-xl bg-teal-700 px-3 py-2 text-xs font-bold text-white">{{names(candidate)}}</button><span v-if="!s.candidates.length" class="text-xs text-rose-600">جانشین واجد شرایطی یافت نشد.</span></div></div>
<p v-if="!coverageSuggestions.length" class="mt-3 text-xs text-slate-500">در حال حاضر شیفت شروع‌شده بدون ورود شناسایی نشد.</p></section>
<section class="rounded-2xl border bg-white p-4"><div class="flex flex-wrap items-center justify-between gap-2"><h2 class="font-black">شاخص‌های عملیاتی کارکنان</h2><input :value="month" type="month" @change="e=>router.get(route('portal.staff-management.index'),{month:e.target.value},{preserveState:true})" class="rounded-xl border-slate-300 text-sm"></div><p class="mt-1 text-xs text-slate-500">برای برنامه‌ریزی ظرفیت و گفت‌وگوی مدیریتی؛ نه رتبه‌بندی علمی، سنجش کیفیت درمان یا تصمیم تنبیهی خودکار.</p>
<div class="mt-3 overflow-x-auto"><table class="w-full min-w-[700px] text-right text-xs"><thead class="bg-slate-50"><tr><th class="p-3">کارمند</th><th class="p-3">روزهای ثبت‌شده</th><th class="p-3">روزهای تأخیر</th><th class="p-3">مجموع تأخیر</th><th class="p-3">کارکرد</th><th class="p-3">خروج ناقص</th></tr></thead><tbody><tr v-for="p in performance" :key="p.organization_id+'-'+p.clinic_id+'-'+p.staff_user_id" class="border-t"><td class="p-3">{{p.name}} {{p.family||''}}</td><td class="p-3">{{p.recorded_days}}</td><td class="p-3">{{p.late_days}}</td><td class="p-3">{{p.late_minutes}} دقیقه</td><td class="p-3">{{hours(p.worked_minutes)}}</td><td class="p-3">{{p.incomplete_days}}</td></tr><tr v-if="!performance.length"><td colspan="6" class="p-5 text-center text-slate-400">داده‌ای برای این ماه ثبت نشده است.</td></tr></tbody></table></div></section>
</main></PortalLayout>
</template>